@paginate(pagination_model=PAGINATION_MODEL)
def describe_trusts(
    self, directory_id: Optional[str] = None, trust_ids: Optional[List[str]] = None
) -> List[Trust]:
    # If directory_id is provided, return trusts for that directory only
    if directory_id:
        self._validate_directory_id(directory_id)
        directory = self.directories[directory_id]
        trusts = directory.trusts
        if trust_ids:
            trusts = [t for t in trusts if t.trust_id in trust_ids]
        return trusts

    # If no directory_id is provided, return all trusts across all directories
    all_trusts = []
    for directory in self.directories.values():
        if trust_ids:
            all_trusts.extend([t for t in directory.trusts if t.trust_id in trust_ids])
        else:
            all_trusts.extend(directory.trusts)
    return all_trusts

